extends SceneTree
var confirmed_count: int = 0
func _initialize() -> void:
 call_deferred("_run")
func _frames(count: int = 4) -> void:
 for i in range(count): await process_frame
func _click_point(point: Vector2) -> void:
 var motion := InputEventMouseMotion.new()
 motion.position = point
 root.push_input(motion, true)
 for pressed: bool in [true, false]:
  var event := InputEventMouseButton.new()
  event.button_index = MOUSE_BUTTON_LEFT
  event.pressed = pressed
  event.position = point
  root.push_input(event, true)
  await process_frame
 await _frames()
func _run() -> void:
 root.gui_embed_subwindows = true
 root.size = Vector2i(1280, 720)
 var dialog := ConfirmationDialog.new()
 dialog.dialog_text = "Confirm independent editor copy"
 root.add_child(dialog)
 dialog.confirmed.connect(func(): confirmed_count += 1)
 dialog.popup_centered(Vector2i(480, 240))
 dialog.position = Vector2i(320, 180)
 await _frames()
 var button: Control = dialog.get_ok_button()
 var old_point: Vector2 = button.get_global_rect().get_center()
 print("BUTTON_COORDS ", old_point, " WINDOW ", dialog.position)
 await _click_point(old_point)
 assert(confirmed_count == 0 and dialog.visible)
 var fixed_point: Vector2 = button.get_global_transform_with_canvas() * (button.size * 0.5)
 if button.get_window() != root: fixed_point += Vector2(button.get_window().position)
 await _click_point(fixed_point)
 assert(confirmed_count == 1 and not dialog.visible)
 print("EMBEDDED_MODAL_POINTER_OK")
 dialog.free()
 quit(0)
